    tl::write_vector(tlw, dismissed_suggestions, [&](TlWriter& tlw633, const auto& e633) { tlw633.write_string(e633); });
    if (custom_pending_suggestion.has_value()) { custom_pending_suggestion.value()->serialize(tlw); }
